analyses = ()
for d in context:
    prompt = "You will be given one document. Determine if it matches this description and extract specific details if applicable.\n\nTarget article description:\n- It is an article about a 19th-century African scholar (the subject is a scholar who lived primarily in the 1800s).\n- The author is from the same country as the subject of the article.\n- The article proposes similar resource-sharing patterns for historic collection as was obtainable in an African country with a landmass between 1,000,000 and 1,300,000 square kilometers (examples of countries in that band include, but are not limited to: South Africa, Ethiopia, Mali, Mauritania, Niger, Angola, Chad, Egypt; do not assume, only use the document content).\n\nYour tasks for the document:\n1) Say whether the document is or contains that exact article (Yes/No/Possibly). If it only references such an article, say 'Possibly' and explain.\n2) If Yes or Possibly, extract the following from the document (only if present in the document):\n   - Article title\n   - Author name and nationality (or country)\n   - Subject (the 19th-century scholar) name and nationality (or country)\n   - The passage where the article proposes similar resource-sharing patterns for historic collections, and identify the comparison country and its landmass if stated or inferable from the document\n   - The full reference list or any references visible in the document. From that list, identify any item(s) that are a symposium paper (conference or symposium proceedings). For each symposium item found, give:\n     * Full reference line as quoted\n     * Extracted symposium paper title (title only)\n3) Provide exact quotes (with minimal surrounding text) from the document supporting each extracted element.\n4) Conclude with a single line starting with 'Conclusion:' followed by Yes/No/Possibly and a one-sentence justification.\n\nOutput format:\nDOC_RESULT_START\nMatch: <Yes/No/Possibly>\nArticleTitle: <if found>\nAuthorCountry: <if found>\nSubjectName: <if found>\nSubjectCountry: <if found>\nResourceSharingPassage: <quote or NA>\nResourceSharingCountryMentioned: <if found>\nReferencesSymposiumPapers:\n- Title: <symposium paper title>\n  FullRef: <quoted reference line>\n[Repeat for all symposium items if multiple or write 'None']\nSupportQuotes:\n- <short quote and what it supports>\nConclusion: <Yes/No/Possibly + brief reason>\nDOC_RESULT_END\n\nNow analyze this document:\nBEGIN_DOCUMENT\n" + d + "\nEND_DOCUMENT"
    result = llm_query(prompt)
    analyses = analyses + (result,)

combined = "\n\n".join(analyses)

final_prompt = "You are given analyses of multiple documents. Your goal is to identify the single document that best matches ALL the following constraints and then provide exactly the symposium paper title from that article’s reference list:\nConstraints to match:\n- The document is (not merely references) an article about a 19th-century African scholar.\n- The author is from the same country as the subject of the article.\n- The article proposes similar resource-sharing patterns for historic collection as were obtainable in an African country with landmass between 1,000,000 and 1,300,000 square kilometers.\n\nIf exactly one document matches all constraints, use that one. If more than one seems to match, choose the best-supported one based on direct quotes. If none fully match but one is 'Possibly' and provides the closest fit with supporting quotes, choose that one.\n\nFrom that chosen article, look at its reference list and identify the item that is a symposium paper (conference/symposium proceedings). Output ONLY the title of that symposium paper. Do not add quotes, explanations, punctuation, or any other words.\n\nIf no symposium paper title can be found for the matching article, output UNKNOWN.\n\nAnalyses:\n" + combined + "\n\nAnswer format: a single line with only the symposium paper title (no quotes, no extra text)."
final_answer = llm_query(final_prompt)
return_result(final_answer)